#!/usr/bin/env node
// Bundle theme.lua + primitives + widget.lua into the `lua` field of a
// widget's demo.preset.json so the preset is directly uploadable to a device
// without any copy-paste. Mirrors what docs/emulator/emulator.js does at load
// time, but produces a static preset so uploading via app.electra.one works.
//
// Usage:
//   node scripts/bundle-preset.js <widget-slug>        # single widget
//   node scripts/bundle-preset.js --all                 # every design-system widget

const fs = require("fs");
const path = require("path");

const ROOT = path.resolve(__dirname, "..");
const LIB = path.join(ROOT, "lib");
const WIDGETS = path.join(ROOT, "widgets");

const DESIGN_SYSTEM = [
  "modern-adsr", "comp-meter", "eq-3band", "spatial-pan",
  "step-seq-16", "arp-viz", "tape-meter", "note-list-16",
  "gallery-primitives", "theme-gallery",
];

const PRIMITIVE_NAMES = [
  "knob", "bar", "led", "meter", "slider",
  "readout", "graph", "grid", "button",
];

function readLua(p) {
  return fs.readFileSync(p, "utf8").replace(/\s+$/, "");
}

// Strip the trailing `return X` so the file can be inlined safely (a
// top-level `return` in the bundle would halt the whole script before
// the widget code runs).
function stripReturn(code, symbol) {
  return code.replace(new RegExp(`\\nreturn ${symbol}\\s*$`), "");
}

// Convert `local function NAME(...)` (the primitive's entry point) into
// `function Theme.NAME(...)` so it lives on the global Theme directly,
// without an IIFE wrapper. Avoids the upvalue-loss issue we hit on the
// device with the previous `(function() ... end)()` pattern.
function attachPrimitive(name, code) {
  const stripped = stripReturn(code, name);
  return stripped.replace(
    new RegExp(`^local function ${name}\\(`, "m"),
    `function Theme.${name}(`
  );
}

function assemble(widgetSlug) {
  const widgetPath = path.join(WIDGETS, widgetSlug, "widget.lua");
  if (!fs.existsSync(widgetPath)) {
    throw new Error(`No widget.lua at ${widgetPath}`);
  }
  const widgetCode = readLua(widgetPath);

  const theme = stripReturn(readLua(path.join(LIB, "theme.lua")), "Theme");
  const primitives = PRIMITIVE_NAMES.map(name => ({
    name,
    code: attachPrimitive(name, readLua(path.join(LIB, "primitives", `${name}.lua`))),
  }));

  const parts = [];
  parts.push("-- === electraone-widgets bundled preset ===");
  parts.push("-- Auto-generated by scripts/bundle-preset.js — do not edit the");
  parts.push("-- 'lua' field by hand; re-run the bundler after editing the");
  parts.push("-- source widget.lua / theme.lua / primitives.");
  parts.push("");
  parts.push("-- ----- lib/theme.lua -----");
  parts.push(theme);
  parts.push("");

  for (const { name, code } of primitives) {
    parts.push(`-- ----- lib/primitives/${name}.lua -----`);
    parts.push(code);
    parts.push("");
  }

  parts.push(`-- ----- widgets/${widgetSlug}/widget.lua -----`);
  parts.push(widgetCode);

  return parts.join("\n");
}

function bundleOne(slug) {
  const presetPath = path.join(WIDGETS, slug, "demo.preset.json");
  if (!fs.existsSync(presetPath)) {
    console.warn(`  skip ${slug}: no demo.preset.json`);
    return;
  }
  const preset = JSON.parse(fs.readFileSync(presetPath, "utf8"));
  const bundled = assemble(slug);
  preset.lua = bundled;
  fs.writeFileSync(presetPath, JSON.stringify(preset, null, 2) + "\n");
  console.log(`  ${slug}: ${bundled.length.toLocaleString()} chars bundled`);
}

const arg = process.argv[2];
if (!arg) {
  console.error("usage: node scripts/bundle-preset.js <slug> | --all");
  process.exit(1);
}

if (arg === "--all") {
  console.log(`Bundling ${DESIGN_SYSTEM.length} design-system widgets:`);
  DESIGN_SYSTEM.forEach(bundleOne);
} else {
  bundleOne(arg);
}
